# Primera clasificación de los materiales que ya hay, según su tipo.
# Es un punto de partida: Oficina puede cambiar la clase de cualquier material desde la web.
TIPOS_SOPORTE = ['Soportes y fijaciones', 'Estructuras solares']
TIPOS_ACCESORIO = [
    'Accesorios hidráulicos', 'Aislamientos', 'Filtros y separadores de lodos', 'Instrumentos de medida',
    'Llenado y vaciado', 'Líquidos y tratamientos', 'Válvulas', 'Pantallas y mandos', 'Repuestos',
    'Protecciones eléctricas', 'Enchufes', 'Material vario', 'Desagües y saneamiento', 'Medidores de energía',
    'Pasarelas y comunicación',
]


def clasificar_materiales(apps, schema_editor):
    Material = apps.get_model('gestion', 'Material')
    # Mano de obra y servicios no son material: se quedan sin clase
    Material.objects.filter(categoria='MOB').update(clase='')
    Material.objects.exclude(categoria='MOB').filter(grupo__in=TIPOS_SOPORTE).update(clase='SOP')
    Material.objects.exclude(categoria='MOB').filter(grupo__in=TIPOS_ACCESORIO).update(clase='ACC')


def crear_hora_peon(apps, schema_editor):
    """Tercer tipo de hora, junto a Oficial y Pareja. Precio provisional: Oficina lo cambia en Materiales."""
    Categoria = apps.get_model('gestion', 'Categoria')
    Material = apps.get_model('gestion', 'Material')
    # En una base de datos vacía aún no hay familias: la hora llega luego con loaddata datos_gregal
    if Categoria.objects.filter(pk='MOB').exists() and not Material.objects.filter(nombre='Hora Peón').exists():
        Material.objects.create(pk=1500, nombre='Hora Peón', categoria_id='MOB', grupo='Horas',
                                unidad='H', precio='25.00', clase='')


def quitar_hora_peon(apps, schema_editor):
    Material = apps.get_model('gestion', 'Material')
    Material.objects.filter(nombre='Hora Peón', consumos__isnull=True).delete()


